import socket

def parse_grid(data):
    grid = {}
    row = 1
    col = 1
    i = 0
    n = len(data)
    while i < n:
        c = data[i]
        if c == '\x1b':
            if i+1 < n and data[i+1] == '[':
                j = i + 2
                params = ''
                while j < n and (data[j].isdigit() or data[j] == ';'):
                    params += data[j]
                    j += 1
                if j < n:
                    final = data[j]
                    if final in 'Hf':
                        parts = params.split(';')
                        if len(parts) >= 2:
                            row = int(parts[0]) if parts[0] else 1
                            col = int(parts[1]) if parts[1] else 1
                        i = j + 1
                        continue
                    elif final == 'd':
                        row = int(params) if params else 1
                        i = j + 1
                        continue
                    elif final == 'G':
                        col = int(params) if params else 1
                        i = j + 1
                        continue
                    else:
                        i = j + 1
                        continue
                else:
                    i = j
                    continue
            else:
                i += 2
                continue
        else:
            if c == '\n':
                row += 1
                col = 1
            elif c == '\r':
                col = 1
            else:
                grid[(row, col)] = c
                col += 1
            i += 1
    return grid

def grid_to_text(grid):
    if not grid:
        return ''
    max_row = max(r for r, c in grid)
    max_col = max(c for r, c in grid)
    lines = []
    for r in range(1, max_row+1):
        line = ''
        for c in range(1, max_col+1):
            line += grid.get((r, c), ' ')
        lines.append(line.rstrip())
    return '\n'.join(lines)

def read_until(s, marker, timeout=5):
    data = b''
    s.settimeout(timeout)
    try:
        while marker not in data:
            chunk = s.recv(4096)
            if not chunk:
                break
            data += chunk
    except socket.timeout:
        pass
    return data

def extract_password(text):
    grid = parse_grid(text)
    text_grid = grid_to_text(grid)
    for line in text_grid.split('\n'):
        if 'PASSWORD' in line:
            idx = line.find('PASSWORD')
            rest = line[idx+len('PASSWORD'):].strip()
            if rest.startswith(':'):
                rest = rest[1:].strip()
            return rest
    return None

