import socket

def build_avl(nums):
    class Node:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None
            self.height = 1

    def height(n):
        return n.height if n else 0

    def balance(n):
        if not n: return 0
        return height(n.left) - height(n.right)

    def update(n):
        if n: n.height = 1 + max(height(n.left), height(n.right))

    def rotate_right(y):
        x = y.left
        T = x.right
        x.right = y
        y.left = T
        update(y)
        update(x)
        return x

    def rotate_left(x):
        y = x.right
        T = y.left
        y.left = x
        x.right = T
        update(x)
        update(y)
        return y

    def insert(node, val):
        if not node:
            return Node(val)
        if val < node.val:
            node.left = insert(node.left, val)
        else:
