import string
from fractions import Fraction

chars = list(" " + string.ascii_lowercase)

def mat_inv(mat):
    n = len(mat)
    aug = [[Fraction(mat[i][j]) for j in range(n)] + [Fraction(1 if i==j else 0) for j in range(n)] for i in range(n)]
    for col in range(n):
        pivot = None
        for row in range(col, n):
            if aug[row][col] != 0:
                pivot = row
                break
        if pivot is None:
            raise Exception("Singular matrix")
        aug[col], aug[pivot] = aug[pivot], aug[col]
        pv = aug[col][col]
        aug[col] = [x / pv for x in aug[col]]
        for row in range(n):
            if row != col:
                factor = aug[row][col]
                aug[row] = [aug[row][j] - factor * aug[col][j] for j in range(2*n)]
    return [[aug[i][n+j] for j in range(n)] for i in range(n)]

M = [[3,6,1],[9,4,2],[1,5,7]]
M_inv = mat_inv(M)

with open('messages.txt') as f:
    messages = []
    for line in f:
        line = line.strip()
        if line:
            messages.append(eval(line))

all_words = []
for i, m in enumerate(messages):
    plain = []
    for j in range(0, len(m), 3):
        block = m[j:j+3]
        if len(block) < 3:
            break
        p = []
        for k in range(3):
            val = sum(M_inv[k][l] * block[l] for l in range(3))
            p.append(val)
        for x in p:
