#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#define N 624
#define M 397
static uint32_t mt[N];
static int mti = N+1;

void init_genrand(uint32_t s) {
    mt[0] = s;
    for (mti = 1; mti < N; mti++) {
        mt[mti] = 1812433253UL * (mt[mti-1] ^ (mt[mti-1] >> 30)) + mti;
        mt[mti] &= 0xffffffffUL;
    }
}

void init_by_array(uint32_t *key, int keylen) {
    int i, j, k;
    init_genrand(19650218UL);
    i = 1; j = 0;
    k = (N > keylen ? N : keylen);
    for (; k; k--) {
        mt[i] = (mt[i] ^ ((mt[i-1] ^ (mt[i-1] >> 30)) * 1664525UL))
          + key[j] + j;
        mt[i] &= 0xffffffffUL;
        i++; j++;
        if (i>=N) { mt[0] = mt[N-1]; i=1; }
        if (j>=keylen) j=0;
    }
    for (k=N-1; k; k--) {
        mt[i] = (mt[i] ^ ((mt[i-1] ^ (mt[i-1] >> 30)) * 1566083941UL))
          - i;
        mt[i] &= 0xffffffffUL;
        i++;
        if (i>=N) { mt[0] = mt[N-1]; i=1; }
    }
    mt[0] = 0x80000000UL;
}

uint32_t genrand_int32(void) {
    uint32_t y;
    static uint32_t mag01[2] = {0x0UL, 0x9908b0dfUL};
    if (mti >= N) {
        int kk;
        if (mti == N+1) init_genrand(5489UL);
        for (kk = 0; kk < N-M; kk++) {
            y = (mt[kk]&0x80000000UL) + (mt[kk+1]&0x7fffffffUL);
            mt[kk] = mt[kk+M] ^ (y >> 1) ^ mag01[y & 1];
        }
        for (; kk<N-1; kk++) {
            y = (mt[kk]&0x80000000UL) + (mt[kk+1]&0x7fffffffUL);
            mt[kk] = mt[kk+(M-N)] ^ (y >> 1) ^ mag01[y & 1];
        }
        y = (mt[N-1]&0x80000000UL) + (mt[0]&0x7fffffffUL);
        mt[N-1] = mt[M-1] ^ (y >> 1) ^ mag01[y & 1];
        mti = 0;
    }
    y = mt[mti++];
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9d2c5680UL;
    y ^= (y << 15) & 0xefc60000UL;
    y ^= (y >> 18);
    return y;
}

int main(int argc, char**argv) {
    unsigned long long s = strtoull(argv[1], 0, 10);
    // Convert to 32-bit words
